import{_ as e,o as a,c as i,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Exploradores de archivos compatibles e integración de diálogos","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/file-manager-support.md","filePath":"es-ES/user-guide/file-manager-support.md","lastUpdated":1787586465000}'),l={name:"es-ES/user-guide/file-manager-support.md"};function r(n,t,d,s,c,g){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="exploradores-de-archivos-compatibles-e-integracion-de-dialogos" tabindex="-1">Exploradores de archivos compatibles e integración de diálogos <a class="header-anchor" href="#exploradores-de-archivos-compatibles-e-integracion-de-dialogos" aria-label="Permalink to &quot;Exploradores de archivos compatibles e integración de diálogos&quot;">​</a></h1><p>Lertaro va más allá de ser un lanzador independiente: se integra profundamente en el Explorador de Windows, exploradores de terceros y cuadros de diálogo de software, agilizando enormemente la apertura, guardado y navegación de carpetas.</p><h2 id="_1-tres-capacidades-principales-de-integracion" tabindex="-1">1. Tres capacidades principales de integración <a class="header-anchor" href="#_1-tres-capacidades-principales-de-integracion" aria-label="Permalink to &quot;1. Tres capacidades principales de integración&quot;">​</a></h2><p>En función de las características de la ventana anfitriona, Lertaro ofrece hasta tres funciones de integración:</p><ul><li><strong>Búsqueda incrustada (Inline Search)</strong>: La barra de búsqueda rápida de Lertaro se incrusta en la parte superior de la ventana o dentro del diálogo, permitiendo buscar en el directorio actual o globalmente sin cambiar de contexto.</li><li><strong>Navegación rápida (Quick Navigation)</strong>: Haz clic central (o doble clic izquierdo) en zonas vacías o en el logotipo incrustado para desplegar un menú en cascada con carpetas abiertas, favoritos, historial y categorías personalizadas.</li><li><strong>Detección de ruta activa (Active Path Detection)</strong>: Reconoce en tiempo real el directorio físico abierto en la ventana anfitriona, limitando automáticamente el ámbito de búsqueda y resolviendo rutas relativas.</li></ul><h2 id="_2-componentes-nativos-de-windows-integrados-de-serie" tabindex="-1">2. Componentes nativos de Windows (Integrados de serie) <a class="header-anchor" href="#_2-componentes-nativos-de-windows-integrados-de-serie" aria-label="Permalink to &quot;2. Componentes nativos de Windows (Integrados de serie)&quot;">​</a></h2><p>Compatibles directamente con el motor central de Lertaro sin necesidad de plugins adicionales:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Tipo de ventana anfitriona</th><th style="text-align:left;">Búsqueda incrustada</th><th style="text-align:left;">Activador de Navegación rápida</th><th style="text-align:left;">Detección de ruta activa</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Explorador de archivos de Windows</strong></td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Doble clic izquierdo o clic central en zonas vacías</td><td style="text-align:left;">Compatible</td></tr><tr><td style="text-align:left;"><strong>Diálogos modernos de Abrir/Guardar</strong></td><td style="text-align:left;">Compatible (Incrustado directamente)</td><td style="text-align:left;">Clic central, o clic izquierdo en el logotipo incrustado</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>Diálogos clásicos de Abrir/Guardar</strong></td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Clic central, o clic izquierdo en el logotipo incrustado</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>Diálogos clásicos &quot;Buscar carpeta&quot;</strong></td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Clic central, o clic izquierdo en el logotipo incrustado</td><td style="text-align:left;">—</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>En los diálogos de selección de archivos, Lertaro ya está incrustado en el propio diálogo, por lo que no requiere detección externa de ruta. Al hacer clic en un destino de Navegación rápida, el diálogo salta directamente a esa carpeta.</p></div><h2 id="_3-exploradores-de-terceros-profesionales-plugins-opcionales" tabindex="-1">3. Exploradores de terceros profesionales (Plugins opcionales) <a class="header-anchor" href="#_3-exploradores-de-terceros-profesionales-plugins-opcionales" aria-label="Permalink to &quot;3. Exploradores de terceros profesionales (Plugins opcionales)&quot;">​</a></h2><p>Para usuarios avanzados que utilicen exploradores de terceros, Lertaro ofrece plugins de integración dedicados. Actívalos en <a href="./settings/plugins.html"><strong>Configuración → Plugins</strong></a> y configura la Búsqueda incrustada y la Navegación rápida por separado:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Explorador de archivos</th><th style="text-align:left;">Búsqueda incrustada</th><th style="text-align:left;">Activador de Navegación rápida</th><th style="text-align:left;">Detección de ruta activa</th><th style="text-align:left;">Tecnología y protocolo de comunicación</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Directory Opus</strong></td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Clic central en la lista de archivos</td><td style="text-align:left;">Compatible</td><td style="text-align:left;">API remota oficial <code>WM_COPYDATA</code></td></tr><tr><td style="text-align:left;"><strong>Total Commander</strong></td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Clic central en la lista de archivos</td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Protocolo de mensajes <code>WM_COPYDATA</code></td></tr><tr><td style="text-align:left;"><strong>XYplorer</strong></td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Clic central en la lista de archivos</td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Comunicación dedicada entre procesos</td></tr><tr><td style="text-align:left;"><strong>Files</strong></td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Clic central en la lista de archivos</td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Marco Windows UI Automation</td></tr><tr><td style="text-align:left;"><strong>One Commander</strong></td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Clic central en la lista de archivos</td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Marco Windows UI Automation</td></tr></tbody></table><h3 id="integracion-avanzada-con-directory-opus" tabindex="-1">Integración avanzada con Directory Opus <a class="header-anchor" href="#integracion-avanzada-con-directory-opus" aria-label="Permalink to &quot;Integración avanzada con Directory Opus&quot;">​</a></h3><ul><li><strong>Columna de tamaño recursivo (Lertaro Tamaño)</strong>: Al activar &quot;Habilitar columna de tamaño Lertaro&quot;, se instala una columna de script personalizada en Directory Opus. Lee los tamaños recursivos directamente del índice en memoria de Lertaro, mostrando el tamaño total de todas las carpetas <strong>sin operaciones de E/S en disco</strong>.</li><li><strong>Guardado permanente</strong>: Tras añadir la columna &quot;Lertaro Tamaño&quot;, haz clic en <strong>Carpeta → Formato de carpetas → Guardar → Guardar formato para todas las carpetas</strong>.</li></ul><h3 id="servicio-de-compatibilidad-con-everything-ipc" tabindex="-1">Servicio de compatibilidad con Everything (IPC) <a class="header-anchor" href="#servicio-de-compatibilidad-con-everything-ipc" aria-label="Permalink to &quot;Servicio de compatibilidad con Everything (IPC)&quot;">​</a></h3><p>En <a href="./settings/general.html#sistema"><strong>Configuración → General → Sistema</strong></a>, activa <strong>Habilitar servicio de compatibilidad Everything (IPC)</strong> para emular la interfaz Win32 IPC de Everything. Herramientas como Directory Opus, Total Commander y Flow Launcher pueden consultar el índice en memoria de Lertaro mediante sus plugins existentes de Everything.</p><h2 id="_4-dialogos-personalizados-de-software-plugins-dedicados" tabindex="-1">4. Diálogos personalizados de software (Plugins dedicados) <a class="header-anchor" href="#_4-dialogos-personalizados-de-software-plugins-dedicados" aria-label="Permalink to &quot;4. Diálogos personalizados de software (Plugins dedicados)&quot;">​</a></h2><p>Muchos programas profesionales emplean ventanas propias en lugar de los diálogos nativos de Windows. Lertaro proporciona plugins dedicados para estas aplicaciones:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Aplicación y tipo de diálogo</th><th style="text-align:left;">Búsqueda incrustada</th><th style="text-align:left;">Activador de Navegación rápida</th><th style="text-align:left;">Notas de integración</th></tr></thead><tbody><tr><td style="text-align:left;">Diálogos Abrir/Guardar de <strong>WPS Office</strong></td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Clic central o clic en el logotipo</td><td style="text-align:left;">Compatible con WPS Writer, Spreadsheets, Presentation y PDF</td></tr><tr><td style="text-align:left;">Diálogo de extracción de <strong>WinRAR</strong></td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Clic central o clic en el logotipo</td><td style="text-align:left;">Selección rápida del directorio de destino</td></tr><tr><td style="text-align:left;">Diálogo de extracción de <strong>Bandizip</strong></td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Clic central o clic en el logotipo</td><td style="text-align:left;">Especificación inmediata de la carpeta de extracción</td></tr><tr><td style="text-align:left;">Diálogo de adición de archivos de <strong>Bandizip</strong></td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Clic central o clic en el logotipo</td><td style="text-align:left;">Selección rápida de archivos fuente</td></tr><tr><td style="text-align:left;">Diálogos Abrir/Guardar de <strong>AutoCAD</strong></td><td style="text-align:left;">Compatible</td><td style="text-align:left;">Clic central o clic en el logotipo</td><td style="text-align:left;">Optimizado para el almacenamiento y consulta de planos CAD</td></tr></tbody></table><p>Los plugins identifican la jerarquía de controles internos, manteniéndose compatibles con independencia de paquetes de idioma o modificaciones visuales de la interfaz.</p>',20)])])}const f=e(l,[["render",r]]);export{u as __pageData,f as default};
